-- First riding mount quests
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`ID` int unsigned NOT NULL, `QuestType` tinyint unsigned NOT NULL, `QuestSortID` smallint NOT NULL, `RewardXPDifficulty` int unsigned NOT NULL, `RewardXPMultiplier` float NOT NULL, `Flags` int unsigned NOT NULL, `AllowableRaces` bigint unsigned NOT NULL, `LogTitle` mediumtext NOT NULL, `LogDescription` mediumtext NOT NULL, `QuestDescription` mediumtext NOT NULL, `VerifiedBuild` int NOT NULL, `RewardChoiceItemID1` int unsigned NOT NULL, `RewardChoiceItemQuantity1` int unsigned NOT NULL, `RewardChoiceItemID2` int unsigned NOT NULL, `RewardChoiceItemQuantity2` int unsigned NOT NULL, `RewardChoiceItemID3` int unsigned NOT NULL, `RewardChoiceItemQuantity3` int unsigned NOT NULL, `RewardChoiceItemID4` int unsigned NOT NULL, `RewardChoiceItemQuantity4` int unsigned NOT NULL, `RewardFactionID1` int unsigned NOT NULL, `RewardFactionValue1` int NOT NULL, `RewardFactionID2` int unsigned NOT NULL, `RewardFactionValue2` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`ID`, `QuestType`, `QuestSortID`, `RewardXPDifficulty`, `RewardXPMultiplier`, `Flags`, `AllowableRaces`, `LogTitle`, `LogDescription`, `QuestDescription`, `VerifiedBuild`, `RewardChoiceItemID1`, `RewardChoiceItemQuantity1`, `RewardChoiceItemID2`, `RewardChoiceItemQuantity2`, `RewardChoiceItemID3`, `RewardChoiceItemQuantity3`, `RewardChoiceItemID4`, `RewardChoiceItemQuantity4`, `RewardFactionID1`, `RewardFactionValue1`, `RewardFactionID2`, `RewardFactionValue2`, `note`) VALUES
(96989, 2, 14, 0, 1.0, 1048576, 128, 'Your First Riding Raptor', 'Inspect the riding raptors to choose your first mount.', 'Ey mon! Today be a big day for ya, I see. Ya think you''re ready to take de reins of one of these fierce creatures, huh?$B$BMost be underestimatin'' how intelligent and savage these beasts be. Ya won''t be findin'' a better, faster or more lethal companion once ya be bonded with it.$B$BSo, you be havin'' an important choice to make. Ya raptor and you will be traversin'' the world together, and the raptor will also be needin'' to choose ya in return.$B$BGo an'' take a look and return to me when ya made ya choice.', 0, 8588, 1, 8591, 1, 8592, 1, 0, 0, 530, 2, 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96994, 2, 1637, 0, 1.0, 1048576, 2, 'Your First Riding Wolf', 'Inspect the riding wolves to choose your first mount.', 'Lok''tar, $c. Come to bond with your first wolf? Good.$B$BThere is no stronger bond than that of an orc and their wolf. They are no mere mount, but are a lifelong companion and friend.$B$BOurs is not a bond chosen by vanity. No, each orc and wolf forms a special bond that goes beyond a mere purchase.$B$BThey will choose you as much as you will choose them. You will understand when you meet them.$B$BGo and find which wolf speaks to you. Return to me when you have your answer.', 0, 5668, 1, 5665, 1, 1132, 1, 1041, 1, 76, 2, 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96996, 2, 16593, 5, 1.0, 1048576, 12884901888, 'Your First Riding Galestrider', 'Inspect the riding striders to choose your first mount.', 'Now that you have completed your training, it would seem the winds wish you to bond with your first strider.$B$BThese galestriders have been ridden by our ancestors for generations. Despite their wispy and slender appearance, they are steadfast and fierce mounts.$B$BYou and your strider will traverse the world together, so you have an important choice to make. Fear not, whatever choice you make will be the right one.$B$BGo examine the striders and return to me when you have made your choice.', 0, 269681, 1, 274930, 1, 269683, 1, 0, 0, 2779, 2, 2778, 2, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96997, 2, 85, 0, 1.0, 1048576, 16, 'A Steed in Death as They Were in Life', 'Inspect the undead riding horses to choose your first mount.', 'Greetings, $c. I imagine I can guess what has brought you to my stables today.$B$BIf you are looking for a mount, you have come to the right place. Be warned though, riding an undead steed is not for the faint of heart.$B$BAs such, you have an important choice to make. You and your undead steed will travel the world together for good or ill. Fear not, whatever choice you make will be the correct one.$B$BGo examine the undead horses and return to me when you have made your choice.', 0, 13332, 1, 13331, 1, 13333, 1, 276063, 1, 68, 2, 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate');
