UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `conditions` t WHERE t.`SourceTypeOrReferenceId` = s.`SourceTypeOrReferenceId` AND t.`SourceGroup` = s.`SourceGroup` AND t.`SourceEntry` = s.`SourceEntry` AND t.`SourceId` = s.`SourceId`) AND EXISTS (SELECT 1 FROM `everlake_slice23_ready` WHERE `quest` = s.`SourceEntry`);
INSERT INTO `conditions` (`SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `ConditionStringValue1`, `Comment`) SELECT `SourceTypeOrReferenceId`, `SourceGroup`, `SourceEntry`, `SourceId`, `ElseGroup`, `ConditionTypeOrReference`, `ConditionTarget`, `ConditionValue1`, `ConditionValue2`, `ConditionValue3`, `ConditionStringValue1`, `Comment` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `k4`, `file`, `note`) SELECT 'conditions', s.`SourceTypeOrReferenceId`, s.`SourceGroup`, s.`SourceEntry`, s.`SourceId`, '2026_11_10_19_world_everlake_import_slice23.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_19_world_everlake_import_slice23.sql', `note` = s.`note`;
