-- First riding mount quests
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`QuestId` int NOT NULL, `PlayerConditionId` int NOT NULL, `QuestgiverCreatureId` int NOT NULL, `locale` varchar(4) NOT NULL, `Text` text NOT NULL, `OrderIndex` int NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`, `locale`, `Text`, `OrderIndex`, `VerifiedBuild`, `note`) VALUES
(96989, 155127, 7952, 'enUS', 'Ey, warlock! I must admit I be surprised to see one of your talents here at me stables.$B$BIf you are looking for a mount, ya have come to the right place, though they ain''t the same as those felsteeds you are accustom to summoning.$B$BEither way, you''re welcome to take a look at our raptors, should ya want one. Most be underestimatin'' how intelligent and savage these beasts be. Ya won''t be findin'' a better, faster or more lethal companion once ya be bonded with it.$B$BGo an'' take a look to see if any catch ya interest and return to me when ya made ya choice.', 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96994, 155127, 3362, 'enUS', '<Ogunaro narrows his eyes as you approach.>$B$BLok''tar, warlock. I must admit I am surprised to see one of your... talents here.$B$BIf you are looking for a riding wolf, you have come to the right place, however know that riding and befriending a wolf is very different from the felsteeds you are accustomed to summoning.$B$BThe bond between orc and wolf is not one chosen by vanity. No, each orc and wolf forms a special bond that goes beyond a mere purchase.$B$BIf you are here to bond with a wolf, I would suggest going to each and examining them. Return to me if you sense a kinship with one.', 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96997, 158357, 4731, 'enUS', 'Greetings, paladin. I must admit I am surprised to see one of your order here at my stables.$B$BIf you are looking for a mount, you have come to the right place, though they may pale in comparison to the chargers you are accustomed to.$B$BRegardless, I encourage you to peruse our steeds, should you want one. Ours are some of the finest steeds in the land, and even though you radiate with holy power they should still bear you as faithfully and without issue.$B$BGo examine the undead horses to see if any are to your liking and return to me when you have made your choice.', 0, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate'),
(96997, 155127, 4731, 'enUS', 'Greetings, warlock. I must admit I am surprised to see one of your talents here at my stables.$B$BIf you are looking for a mount, you have come to the right place, though they may pale in comparison to the felsteeds you are accustomed to summoning.$B$BRegardless, I encourage you to peruse our steeds, should you want one. Ours are some of the finest steeds in the land, and they should still bear you as faithfully as your summoned infernal felsteed.$B$BThough I would advise against lighting the skeletal horses on fire. That is an aesthetic best saved for the unholy creatures you and your council conjure.$B$BGo examine the undead horses to see if any are to your liking and return to me when you have made your choice.', 1, 0, 'Efficient Games Forever 70862 quest cache; Wowhead riding guide vendor and Apprentice Riding gate');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_description_conditional` t WHERE t.`QuestId` = s.`QuestId` AND t.`PlayerConditionId` = s.`PlayerConditionId` AND t.`QuestgiverCreatureId` = s.`QuestgiverCreatureId`) AND EXISTS (SELECT 1 FROM `everlake_slice23_ready` WHERE `quest` = s.`QuestId`);
INSERT INTO `quest_description_conditional` (`QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`, `locale`, `Text`, `OrderIndex`, `VerifiedBuild`) SELECT `QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`, `locale`, `Text`, `OrderIndex`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `file`, `note`) SELECT 'quest_description_conditional', s.`QuestId`, s.`PlayerConditionId`, s.`QuestgiverCreatureId`, '2026_11_10_19_world_everlake_import_slice23.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_19_world_everlake_import_slice23.sql', `note` = s.`note`;
DROP TEMPORARY TABLE `everlake_import_stage`;

DROP TEMPORARY TABLE `everlake_slice23_ready`;
